Here is the root cause:
The bug is caused by the failure to flush error routes (such as 'blackhole' or 'unreachable') when a network namespace is dismantled. These routes are not marked as dead and thus are skipped during the flushing process, leading to memory leaks as they remain unreferenced in memory.

Here is the patch:
 /* Caller must hold RTNL. */
-int fib_table_flush(struct net *net, struct fib_table *tb)
+int fib_table_flush(struct net *net, struct fib_table *tb, bool flush_all)
 {
 	struct trie *t = (struct trie *)tb->tb_data;
 	struct key_vector *pn = t->kv;
 	unsigned long cindex = 1;
 	struct hlist_node *tmp;
 	struct fib_alias *fa;
 	int found = 0;

 	/* walk trie in reverse order */
 	for (;;) {
 		unsigned char slen = 0;
 		struct key_vector *n;

 		if (!(cindex--)) {
 			t_key pkey = pn->key;

 			/* cannot resize the trie vector */
 			if (IS_TRIE(pn))
 				break;

 			/* update the suffix to address pulled leaves */
 			if (pn->slen > pn->pos)
 				update_suffix(pn);

 			/* resize completed node */
 			pn = resize(t, pn);
 			cindex = get_index(pkey, pn);

 			continue;
 		}

 		/* grab the next available node */
 		n = get_child(pn, cindex);
 		if (!n)
 			continue;

 		if (IS_TNODE(n)) {
 			/* record pn and cindex for leaf walking */
 			pn = n;
 			cindex = 1ul << n->bits;

 			continue;
 		}

 		hlist_for_each_entry_safe(fa, tmp, &n->leaf, fa_list) {
 			struct fib_info *fi = fa->fa_info;

-			if (!fi || !(fi->fib_flags & RTNH_F_DEAD) ||
-			    tb->tb_id != fa->tb_id) {
+			if (!fi || tb->tb_id != fa->tb_id ||
+			    (!(fi->fib_flags & RTNH_F_DEAD) &&
+			     !fib_props[fa->fa_type].error)) {
+				slen = fa->fa_slen;
+				continue;
+			}
+
+			/* Do not flush error routes if network namespace is
+			 * not being dismantled
+			 */
+			if (!flush_all && fib_props[fa->fa_type].error) {
 				slen = fa->fa_slen;
 				continue;
 			}

 			call_fib_entry_notifiers(net, FIB_EVENT_ENTRY_DEL,
 						 n->key,
 						 KEYLENGTH - fa->fa_slen, fa,
 						 NULL);
 			hlist_del_rcu(&fa->fa_list);
 			fib_release_info(fa->fa_info);
 			alias_free_mem_rcu(fa);
 			found++;
 		}

 		/* update leaf slen */
 		n->slen = slen;

 		if (hlist_empty(&n->leaf)) {
 			put_child_root(pn, n->key, NULL);
 			node_free(n);
 		}
 	}

 	pr_debug("trie_flush found=%d\n", found);
 	return found;
 }



